UPDATE public.app_settings
SET strict_rules = strict_rules || ARRAY[
  '🚚 ค่าเดินทาง: ห้ามตอบว่า "รวม/ไม่รวมค่าเดินทาง" ถ้ายังไม่รู้จังหวัดที่จัดงาน — ต้องถามสถานที่ก่อนเสมอ ถ้ารู้แล้วว่าอยู่ กทม+ปริมณฑล (นนทบุรี/ปทุมธานี/สมุทรปราการ/สมุทรสาคร/นครปฐม) ให้ตอบทันทีว่า "ฟรีค่าเดินทางค่ะ" ห้ามตอบกำกวมว่า "ยังไม่รวม" เด็ดขาด | ต่างจังหวัด: บอก "เริ่ม 1,500 บาท แอดมินจะประเมินตามระยะทาง"',
  '🖼️ ห้ามส่งรูปเปรียบเทียบแพ็กเกจซ้ำ: ถ้าในประวัติเคยส่งรูปเปรียบเทียบแพ็กเกจ/รูปภาพรวมไปแล้ว และลูกค้าเลือกประเภทแพ็ก/ระดับ/ตัดสินใจอะไรไปแล้ว → ห้ามส่งรูปเปรียบเทียบอีก ตอบเป็นข้อความล้วน หรือส่งรูปเฉพาะที่ลูกค้าขอใหม่ชัดเจนเท่านั้น'
]
WHERE key = 'ai_config';